from collections import deque


def maxMinPath(grid):
    m, n = len(grid), len(grid[0])

    def reach(t):
        if grid[0][0] < t or grid[m - 1][n - 1] < t:
            return False
        seen = [[False] * n for _ in range(m)]
        seen[0][0] = True
        q = deque([(0, 0)])
        while q:
            i, j = q.popleft()
            if i == m - 1 and j == n - 1:
                return True
            for x, y in ((i + 1, j), (i - 1, j), (i, j + 1), (i, j - 1)):
                if 0 <= x < m and 0 <= y < n and not seen[x][y] and grid[x][y] >= t:
                    seen[x][y] = True
                    q.append((x, y))
        return False

    vals = sorted({v for row in grid for v in row})
    lo, hi = 0, len(vals) - 1
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if reach(vals[mid]):
            lo = mid
        else:
            hi = mid - 1
    return vals[lo]
